function createHehuanRewind(C){
  const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
  function diff(a,b,path=[],out=[]){if(same(a,b))return out;if(C.obj(a)&&C.obj(b)){for(const k of new Set([...Object.keys(a),...Object.keys(b)]))diff(a[k],b[k],[...path,k],out);}else out.push({path,before:C.clone(a),after:C.clone(b),existed:a!==undefined});return out;}
  function read(o,path){for(const k of path){if(o==null)return undefined;o=o[k];}return o;}
  function put(o,p,value,exists=true){let target=o;for(const k of p.slice(0,-1)){if(!C.obj(target[k]))target[k]={};target=target[k];}if(exists)target[p.at(-1)]=C.clone(value);else delete target[p.at(-1)];}
  const prefix=(a,b)=>a.length<=b.length&&a.every((v,i)=>v===b[i]);
  function record(saved,before,after,scope){
    const rows=['合欢宗','主角'].flatMap(k=>diff(before.stat_data[k],after.stat_data[k],[k]));
    // 有新的剧情更新落到原操作字段时，以更新后的资料作为新的可撤销起点。
    if(!saved||saved.scope!==scope||saved.rows.some(r=>!same(read(before.stat_data,r.path),r.after)))saved={scope,rows:[],drafts:[]};
    const next=C.clone(saved);
    for(const row of rows){
      const ancestor=next.rows.find(r=>prefix(r.path,row.path));
      if(ancestor){ancestor.after=C.clone(read(after.stat_data,ancestor.path));continue;}
      const descendants=next.rows.filter(r=>prefix(row.path,r.path));
      if(descendants.length){const box={value:C.clone(row.before)};for(const child of descendants)put(box,['value',...child.path.slice(row.path.length)],child.before,child.existed);row.before=box.value;next.rows=next.rows.filter(r=>!descendants.includes(r));}
      next.rows.push(row);
    }
    next.rows=next.rows.filter(r=>!same(r.before,r.after));return next;
  }
  function restore(saved,data,scope){if(!saved||saved.scope!==scope)return {data:C.clone(data),changed:false};const n=C.clone(data),conflict=saved.rows.find(r=>!same(read(n.stat_data,r.path),r.after));if(conflict)throw Error('本楼资料后来已有剧情更新，未覆盖新记录；可单独撤回尚未确认的意向。');for(const r of saved.rows)put(n.stat_data,r.path,r.before,r.existed);return {data:n,changed:saved.rows.length>0,drafts:saved.drafts||[]};}
  function draft(saved,scope,before,after){const n=saved&&saved.scope===scope?C.clone(saved):{scope,rows:[],drafts:[]};n.drafts.push({before,after});return n;}
  function clean(text,rows){let result=text;for(const row of [...rows].reverse())if(result===row.after)result=row.before;return result;}
  return {same,diff,record,restore,draft,clean};
}
