  function tasks(){const rows=C.catalog(S()),fac=[...new Set(rows.map(r=>r.place))],records=Object.entries(X().差事);let items=ui.taskFilter==='pending'?records.filter(([,r])=>!['已撤回','未获准','已结算','已取消'].includes(r.状态)).map(([id,r])=>({recordId:id,...r})):rows.filter(t=>ui.taskFilter!=='external'||t.scope==='external');if(ui.facility!=='all')items=items.filter(t=>(t.place||t.地点)===ui.facility);const total=items.length,max=Math.max(1,Math.ceil(total/8));ui.taskPage=Math.min(ui.taskPage,max-1);return `<div class="hh-filterbar">${[['catalog','全部岗位 '+rows.length],['pending','在办 '+records.filter(([,r])=>!['已撤回','未获准','已结算','已取消'].includes(r.状态)).length],['external','外包 / 外勤']].map(([id,t])=>B(t,'task-filter',attrs('filter',id)+' aria-pressed="'+(ui.taskFilter===id)+'"')).join('')}<label class="hh-inline-select">按设施 <select id="hh-task-facility"><option value="all">全部设施</option>${fac.map(f=>`<option ${f===ui.facility?'selected':''}>${E(f)}</option>`).join('')}</select></label></div><div class="hh-task-overview">岗位可先问询，具体来客、日期与实收由掌事核准。</div><div class="hh-task-grid">${items.slice(ui.taskPage*8,ui.taskPage*8+8).map(t=>{if(t.recordId)return `<article class="hh-task-job" data-record="${E(t.recordId)}"><div class="hh-job-top"><small>${E(t.类型)}</small><span class="hh-chip">${E(t.状态)}</span></div><h3>${E(t.名称)}</h3><p>${E(t.说明||'')}</p><div class="hh-task-meta"><span>${E(t.日期||'日期待议')}</span><span>${F(t.实收报酬??t.约定报酬)} ${E(t.报酬单位)} / ${E(t.期限单位||'次')}</span></div><div class="hh-task-actions">${['待确认','未获准'].includes(t.状态)?B('撤回意向','task-cancel',attrs('id',t.recordId)):B('问询进度','record-ask',attrs('id',t.recordId))}${['已完成','待结算'].includes(t.状态)?B('领取并入账','task-settle',attrs('id',t.recordId),true)+B('原卡已付，仅记账','task-mark-paid',attrs('id',t.recordId)):''}</div></article>`;const pending=records.find(([,r])=>r._凭据?.目录===t.id&&r._凭据?.地点===P()&&!['已撤回','未获准','已结算','已取消'].includes(r.状态));return `<article class="hh-task-job ${t.scope==='external'?'hh-external-job':''}"><div class="hh-job-top"><small>${E(t.type)}</small><span class="hh-chip">${pending?E(pending[1].状态):t.allowed?'可拟接':'待许可'}</span></div><h3>${E(t.name)}</h3><p>${E(t.desc)}</p><div class="hh-task-meta"><span>${E(t.place)}</span><span>${E(t.pricing)} ${F(t.base)} ${E(t.unit)} / ${E(t.period)}</span></div><div class="hh-task-actions">${pending?['待确认','未获准'].includes(pending[1].状态)?B('撤回意向','task-cancel',attrs('id',pending[0])):B('查看在办','task-filter','data-filter="pending"'):B('拟接','task-accept',attrs('id',t.id),true,!t.allowed)}${B('问安排','task-ask',attrs('id',t.id))}<small>${E(t.allowed?'':t.access)}</small></div></article>`;}).join('')||empty('暂没有相应差事。')}</div><div class="hh-task-pagination"><span>共${F(total)}项 · 第${ui.taskPage+1}/${max}页</span><div>${B('上一页','task-prev','',false,ui.taskPage===0)}${B('下一页','task-next','',false,ui.taskPage>=max-1)}</div></div>`;}
  function ranks(){const t=now(),keys=Object.values(X().月榜).filter(r=>r.地点===P()).map(r=>r.月份).sort((a,b)=>C.keyIndex(a)-C.keyIndex(b));if(!ui.rankManual||!ui.rankKey||!keys.includes(ui.rankKey))ui.rankKey=t?.key;const r=C.ranking(S(),ui.rankKey);if(!r)return empty('当前日期或名册尚未确定，待核对后留榜。');const tr=(p,index,summary=false)=>`<tr class="${p.player?'hh-you':p.anchor?'hh-champion':''}" ${summary?'data-player-summary':''}><td class="hh-rank-no">${summary?(r.rank?F(r.rank):'—'):String(index+1).padStart(2,'0')}</td><td><span class="hh-rank-name">${E(p.name)}${p.player?' · 你':''}</span>${summary&&!r.eligible?'<small>未上榜</small>':''}</td><td>${F(p.revenue)}</td><td>${F(p.fame)}</td><td>${F(p.charm)}</td><td class="hh-rank-score">${F(p.score)}</td></tr>`;return `<div class="hh-filterbar"><label>已留存月份 <select id="hh-rank-month">${keys.map(k=>`<option ${k===ui.rankKey?'selected':''}>${E(k)}</option>`).join('')}</select></label></div><div class="hh-rank-summary"><h3>${N()} · ${P()==='baihua'?'百花芳谱':'金华月榜'}</h3><p>登榜基准80分 · ${P()==='baihua'?'五年一次':'三年一次'}正式花魁考评</p></div><div class="hh-table-wrap"><table class="hh-rank-table"><thead><tr><th>名次</th><th>名籍</th><th>营业</th><th>知名度</th><th>魅力</th><th>综合</th></tr></thead><tbody>${r.top.map((p,i)=>tr(p,i)).join('')}${tr(r.player,10,true)}</tbody></table></div><p class="hh-bottom-note">营业60% · 知名度25% · 魅力15%。营业基准${F(C.businessBase(P()))}下品／月，最高100分；知名度除10后参与计算。个人参考额不改变排名。本人名次只指登记参榜者，月榜不自动授予身份。</p>${X()._旧版记录?'<p class="hh-bottom-note">旧版指标与榜单已留存旧档，不混入新版评分。</p>':''}${B('问询正式考评','ask','data-kind="rank"')}`;}

  function quote(){const x=X().素养,p=P(),base=p==='baihua'?(ui.quoteArt==='曲艺'?30:24):(ui.quoteArt==='曲艺'?180:160),unit=p==='baihua'?'中品':'下品',style=C.charmPercent(x.魅力),skill=100+Math.round(x[ui.quoteArt]*.25),match=ui.quotePref===ui.quoteArt?115:100,total=Math.round(base*style*skill*match/1000000);return `<span>预计艺酬</span><div><strong>${F(total)}</strong> ${unit} / 场</div><small>基础${base} × 风仪${style}% × 艺能${skill}% × 雅好${match}%</small>`;}
  function ledger(){const x=X();return `<div class="hh-account"><section class="hh-box"><h3>本月往来账簿</h3><div class="hh-money-big">${F(x.账目.本月实收下品)} <small>下品等值实收</small></div>${dl([['现有灵石',safeMoney()],['宗门贡献',F(S().主角.宗门贡献)+' 点'],['参考营业额',F(x.账目.参考营业额下品)+' 下品 / 月']])}<div class="hh-control"><label for="hh-target">个人参考额（下品等值）</label><input id="hh-target" type="number" min="0" step="1" value="${C.int(x.账目.参考营业额下品)}"></div>${B('保存参考额','target-save')}<p class="hh-bottom-note">原书无接客业绩要求；此数只供规划，不改变月榜营业基准，不设罚款。</p><div class="hh-control"><label for="hh-convert">灵石兑换贡献（下品数）</label><input id="hh-convert" type="number" min="1" step="1" value="100"></div>${B('兑换贡献','convert','',true)}<p class="hh-bottom-note">1下品＝1贡献，单向兑换。</p></section><section class="hh-box"><h3>歌舞曲艺估价</h3><div class="hh-control"><label for="hh-art-type">艺事</label><select id="hh-art-type">${['曲艺','舞蹈'].map(v=>`<option ${v===ui.quoteArt?'selected':''}>${v}</option>`).join('')}</select></div><div class="hh-control"><label for="hh-art-pref">宾客雅好</label><select id="hh-art-pref">${['清谈','曲艺','舞蹈'].map(v=>`<option ${v===ui.quotePref?'selected':''}>${v}</option>`).join('')}</select></div><div class="hh-quote" id="hh-quote">${quote()}</div><p class="hh-bottom-note">性服务、长包及客房分别依原书物价核算；此处仅估歌舞曲艺的酬金。</p>${B('问询兑换功法、丹药与法器','ask','data-kind="exchange"')}</section></div>${receipts()}${deals()}`;}
  function receipts(){const rows=Object.values(X()._结算).slice(-30).reverse();return `<div class="hh-table-wrap"><table><thead><tr><th>时间</th><th>事项</th><th>收支</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.时间)}</td><td>${E(r.名称)}</td><td>${r.方向==='收入'?'＋':'－'}${F(r.下品)} 下品等值</td></tr>`).join('')||'<tr><td colspan="3">尚无脚本入账凭据。</td></tr>'}</tbody></table></div>`;}
  function deals(){const rows=Object.entries(X().兑换);return '<section class="hh-box"><div class="hh-section-heading"><h3>兑换回帖与可供物资</h3>'+B('问询当前库存','ask','data-kind="exchange"')+'</div>'+rows.map(([id,r])=>'<article class="hh-job"><div class="hh-job-top"><h4>'+E(r.名称||r.物品||id)+'</h4><span class="hh-chip">'+E(r.状态||'待核对')+'</span></div>'+dl([['数量',F(r.数量||1)],['价格',r.价格==null?'待议':F(r.价格)+' '+(r.灵石品级||'贡献点')],['说明',r.说明||'']])+B('核对此项','deal-ask',attrs('id',id))+'</article>').join('')+(rows.length?'':'<p>尚未取得物资清单，可先向掌事问询功法、丹药、法器与材料。</p>')+'</section>';}
  function opportunities(){const rows=Object.entries(S().机遇||{});return rows.length?'<section class="hh-box"><h3>原卡机遇 · 可自行记期</h3>'+rows.map(([name,r])=>'<article class="hh-job"><h4>'+E(name)+'</h4><p>'+E(r.目标||'约期尚待本人决定。')+'</p>'+B('记入行历','opportunity-note',attrs('name',name))+'</article>').join('')+'</section>':'';}
  function mods(){const g=C.MODS.find(g=>g.name===ui.modGroup)||C.MODS[0],selected=X().目录清单,done=C.completedMods(X()),records=Object.values(X().改造记录);return `<div class="hh-filterbar">${C.MODS.map(g=>B(g.name+' '+g.items.length,'mod-group',attrs('group',g.name)+' aria-pressed="'+(g.name===ui.modGroup)+'"')).join('')}</div><div class="hh-catalog-grid">${g.items.map((n,i)=>{const complete=done.get(n),r=complete||records.filter(r=>r.名称===n).at(-1);return `<button type="button" class="hh-catalog-item ${complete?'hh-mod-complete':''}" data-action="mod-select" data-name="${E(n)}" data-state="${E(r?.状态||'未申请')}" aria-pressed="${selected.includes(n)}" ${complete?'disabled':''}><span class="hh-catalog-number">${String(i+1).padStart(2,'0')}</span><span>${E(n)}${r?'<small class="hh-mod-state">'+E(r.状态)+(complete&&r.日期?' · '+E(r.日期):'')+'</small>':''}</span><span aria-hidden="true">${complete?'已完成':selected.includes(n)?'✓':'＋'}</span></button>`;}).join('')}</div><div class="hh-catalog-selection"><p>${selected.length?selected.map(E).join('、'):'尚未列入条目。'}</p><div class="hh-row">${B('整理问询笺','mod-ask','',true,!selected.length)}${B('清空所选','mod-clear','',false,!selected.length)}</div></div><p class="hh-bottom-note">勾选只整理目录，批准也不等于完成。实际完成后显示标记，按类别计入魅力，同名不重复计算。</p><section class="hh-box"><h3>已登记记录</h3>${records.map(r=>`<article class="hh-mod-record"><p><strong>${E(r.名称)}</strong> · ${E(r.状态||'待核对')}${r.日期?' · '+E(r.日期):''}</p>${r.结论?'<p>'+E(r.结论)+'</p>':''}</article>`).join('')||'<p>尚无申请或结果记录。</p>'}</section>`;}

  function calendar(){const t=now();if(!t)return empty('世界当前时间尚不能识别，请先核对元会历日期。');if(ui.calendar==null)ui.calendar=C.monthIndex(t);const m=C.fromMonth(ui.calendar),len=new Date(C.utc(m.y,m.m+1,0)).getUTCDate(),start=new Date(C.utc(m.y,m.m,1)).getUTCDay(),events=C.events(S(),m.y,m.m);ui.day=Math.min(ui.day||t.d,len);const selected=events.filter(e=>e.d===ui.day);return `<div class="hh-section-heading"><h3>${m.y}年${m.m}月</h3><div class="hh-row">${B('上月','month-prev')}${B('今日','month-current')}${B('下月','month-next')}</div></div><div class="hh-calendar">${'日一二三四五六'.split('').map(d=>'<div class="hh-weekday">'+d+'</div>').join('')}${Array.from({length:start},()=>'<span></span>').join('')}${Array.from({length:len},(_,i)=>{const d=i+1,n=events.filter(e=>e.d===d).length;return `<button type="button" class="hh-day" data-action="day" data-day="${d}" aria-pressed="${ui.day===d}"><span>${d}</span>${n?'<small>'+n+'项</small>':''}</button>`;}).join('')}</div><section class="hh-calendar-detail" id="hh-day-detail"><div class="hh-section-heading"><h3>${m.m}月${ui.day}日</h3>${B('记一件事','note-form')}</div>${selected.map((e,i)=>`<article class="hh-job"><div class="hh-job-top"><div><small>${E(e.type)} · ${E(e.place)}</small><h4>${E(e.title)}</h4></div>${B('收起本次提醒','event-hide',attrs('index',events.indexOf(e)))}</div>${e.status?'<p>'+E(e.status)+'</p>':''}</article>`).join('')||empty('此日未有提醒。')}${ui.noteForm?`<form id="hh-note-form"><div class="hh-control"><label for="hh-note-name">事项</label><input id="hh-note-name" maxlength="100" value="${E(ui.noteTitle)}" required></div><div class="hh-control"><label for="hh-note-date">日期</label><input id="hh-note-date" type="date" value="${m.y}-${String(m.m).padStart(2,'0')}-${String(ui.day).padStart(2,'0')}"></div><div class="hh-control"><label for="hh-note-repeat">周期</label><select id="hh-note-repeat"><option>不重复</option><option>每周</option><option>每月</option><option>每年</option></select></div><div class="hh-control"><label for="hh-note-kind">类型</label><select id="hh-note-kind">${['本人记事','课程约期','个人机遇','同门约定'].map(k=>'<option '+(ui.noteKind===k?'selected':'')+'>'+k+'</option>').join('')}</select></div><div class="hh-row">${B('收入行历','note-save','',true)}${B('暂不记','note-cancel')}</div></form>`:''}</section><p class="hh-bottom-note">收起只取消这一次提醒，不完成任务、不结算报酬；重要日程与未来周期继续保留。</p>${B('恢复本月收起的提醒','month-unhide')}${opportunities()}`;}
  function life(){const x=X(),news=Object.entries(x.闲闻).filter(([,r])=>r.状态!=='已归档'),clubs=Object.entries(x.雅集);return `<div class="hh-two-col"><section class="hh-box"><h3>${isMember()?'楼中近事':'风物拾闻'}</h3>${news.map(([,r])=>`<article class="hh-job"><small>${E(r.日期||'日期待核对')} · ${E(r.来源||'来源待核对')}</small><h4>${E(r.名称)}</h4><p>${E(r.内容||'')}</p></article>`).join('')||'<p>尚无新近消息。</p>'}${B('问询近日消息','ask','data-kind="life"')}</section><section class="hh-box"><h3>同门雅集</h3>${clubs.map(([id,r])=>`<article class="hh-job"><div class="hh-job-top"><h4>${E(r.名称)}</h4><span class="hh-chip">${E(r.状态||'未加入')}</span></div><p>${E(r.简介||'')}</p><small>${E(r.地点||'场所待议')} · 会日 ${Array.isArray(r.会日)?r.会日.map(F).join('、'):'待议'}</small><div class="hh-row">${B(r.状态==='已加入'?'问询近次活动':r.状态==='待确认'?'撤回递帖':'递帖结识',r.状态==='待确认'?'club-withdraw':'club-ask',attrs('id',id))}</div></article>`).join('')||'<p>尚未登记雅集。</p>'}${B('结识或发起雅集','ask','data-kind="club"')}</section></div>`;}
  function guestCard(){return `<div class="hh-two-col"><div class="hh-profile-art"><span class="hh-kicker">${P()==='baihua'?'百花签':'登楼腰牌'}</span><h3>${E(title())}</h3><p>${E(X().档案.凭证)}</p></div><section class="hh-box"><h3>来者有帖</h3>${dl([['所至之处',N()],['所持凭证',X().档案.凭证],['累计消费',F(X().账目.累计消费下品)+' 下品等值'],['宾客品级',P()==='baihua'?C.tier(S()):'以腰牌为准'],['核验状态',X().档案.凭证==='无'?'尚待登记':'按当前登记核验']])}<div class="hh-row">${B('问询登记或客牌','ask','data-kind="credential"',true)}${B('查看可往之处','open','data-page="permissions"')}</div></section></div>`;}
  function permissions(){const rows=P()==='baihua'?[['外谷','流芳津 · 芳华集 · 烟霞街'],['中谷','迎春馆 · 听风阁 · 流霞台'],['内谷','流香院 · 听雨居 · 玉露泉'],['谷顶','欲湖 · 揽星楼'],['机密重地','沉香窟与内部案牍']]:[['一至四层','广纳厅 · 悬壶廊 · 解佩汤 · 戏楼'],['五层','锦瑟别苑 · 私人居所'],['六层','天香暖阁 · 高级客房'],['七至八层','问刑轩 · 玄机密阁 · 清宁居'],['九层','紫宸别馆']];return rows.map(([z,n])=>`<article class="hh-job"><div class="hh-job-top"><div><span class="hh-kicker">${C.guestAccess(S(),z)?'凭证可往':'尚须许可'}</span><h3>${z}</h3></div><span class="hh-chip">${C.guestAccess(S(),z)?'已解锁':'锁定'}</span></div><p>${n}</p><div class="hh-job-footer"><small>通行、预约与私人居所许可分别核验。</small>${B('问询此处','permission-ask',attrs('zone',z),false,!C.guestAccess(S(),z))}</div></article>`).join('');}
  function booking(){const rows=P()==='baihua'?[['听风阁茶席','中谷'],['流觞苑宴席','中谷'],['玉露泉汤屋','内谷'],['接客与专侍安排','外谷']]:[['听竹小筑茶席','一至四层'],['万籁戏楼雅座','一至四层'],['天香暖阁客房','六层'],['侍寝预约','一至四层']];return rows.map(([n,z])=>`<article class="hh-job"><div class="hh-job-top"><h3>${n}</h3><span class="hh-chip">${C.guestAccess(S(),z)?'可问询':'待核凭证'}</span></div><p>先问日期、费用和可供安排，确认后再预约。</p>${B('问询安排','book',attrs('name',n),false,!C.guestAccess(S(),z))}</article>`).join('')+`<section class="hh-box"><h3>已留之约</h3>${Object.entries(X().预约).map(([id,r])=>`<article class="hh-job"><h4>${E(r.名称)}</h4><p>${E(r.日期||'日期待议')} · ${E(r.状态||'待确认')}</p>${['待确认','问询中'].includes(r.状态)?B('撤回问询','booking-cancel',attrs('id',id)):B('问询此约','booking-ask',attrs('id',id))}</article>`).join('')||'<p>尚无预约记录。</p>'}</section>`;}
  function guestLedger(){return `<div class="hh-two-col"><section class="hh-box"><h3>往来实付</h3><div class="hh-money-big">${F(X().账目.累计消费下品)} <small>下品等值</small></div>${dl([['凭证',X().档案.凭证],['钱包',safeMoney()],['未确认预约','不计入累计消费']])}${B('核对往来账目','ask','data-kind="guestledger"')}</section><section class="hh-box"><h3>${P()==='baihua'?'百花签品级':'登楼门资'}</h3>${P()==='baihua'?dl([['低阶','不足5000中品'],['中阶','5000至未满100000中品'],['高阶','满100000中品'],['顶级','高阶且经宗门认定']]):dl([['问仙牌','50下品 · 一至四层'],['锦绣牌','500下品＝5中品 · 一至六层'],['金阙牌','5上品 · 贵宾核验']])}<p class="hh-bottom-note">私宅、机密区域与特定活动仍须各自许可。</p></section></div>${receipts()}`;}
