  host[KEY]=dispose;
  window.addEventListener('pagehide',dispose,{once:true});
  startup('正在连接酒馆助手','等待角色脚本接口就绪。');
  while(!stopped&&!['getChatMessages','injectPrompts','eventOn'].every(k=>api(k)))await new Promise(r=>setTimeout(r,250));
  if(stopped)return;
  startup('等待MVU','正在接入原卡共享的MVU接口；就绪后自动读取当前楼层。');
  if(api('waitGlobalInitialized'))Promise.resolve().then(()=>api('waitGlobalInitialized')('Mvu')).then(value=>{if(!stopped&&validM(value))shared=value;}).catch(error=>{if(!stopped)startup('等待MVU','共享接口尚未接入：'+error.message+'。保持原MVU开启，脚本会继续重试。');});
