  for(const k of ['MESSAGE_SWIPED','MESSAGE_SENT','MESSAGE_RECEIVED','MESSAGE_EDITED','MESSAGE_UPDATED','MESSAGE_DELETED','MESSAGE_SWIPE_DELETED','MORE_MESSAGES_LOADED','CHARACTER_MESSAGE_RENDERED'])if(events[k])hold(on(events[k],()=>{if(k==='MESSAGE_SWIPED'){cancelUpdate();notice='';intent=null;}schedule();}));
