  for(const k of ['GENERATION_ENDED','GENERATION_STOPPED'])if(events[k])hold(on(events[k],()=>{busy=false;if(!M()?.isDuringExtraAnalysis?.())mvuBusy=false;queueUpdate();}));
  for(const k of ['MESSAGE_RECEIVED','MESSAGE_EDITED','MESSAGE_UPDATED'])if(events[k])hold(on(events[k],()=>queueUpdate()));
  const roots=new WeakMap(),me=M().events||{};
