  const filter=(data,commands,text)=>{if(C.obj(data)&&!roots.has(data)){const fresh=read(),present=(fresh?.last?.message===text?fresh.data?.stat_data?.合欢宗:null)||data.stat_data?.合欢宗;roots.set(data,present?C.clone(present):null);}U.filter(commands);};
  for(const name of [me.COMMAND_PARSED,me.COMMAND_PARSED&&me.COMMAND_PARSED+'_ended_for_zod'])if(name)hold(on(name,filter));
